"""Compile reviewed QNAP TS-464-8G for SQL23; catalogs16-22 remain frozen."""
from __future__ import annotations
import argparse
import importlib.util
import json
import os
from pathlib import Path
import sys
import tempfile
ROOT = Path(__file__).absolute().parents[1]
_spec = importlib.util.spec_from_file_location('hardware_catalog_helpers23', ROOT/'tools/build_hardware_catalog22.py')
g = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(g)
c = g.c
SOURCE='development/hardware/catalog-qnap-v1.json'
FACTS='development/hardware/qnap-ts464-8g.facts.json'
LOCK='development/hardware/catalog-schema23.lock.json'
BASE='development/server/database/022-diskstation-hardware.sql'
SERVER='development/server/src/RackClick.Server/QnapHardwareProfiles.Generated.cs'
FRONTEND='development/frontend/src/hardware-qnap.generated.json'
SQL='development/server/database/023-qnap-hardware.sql'
MANIFEST='development/hardware/catalog-qnap.manifest.json'
TARGETS='development/server/src/RackClick.Server/QnapHardware.Generated.targets'
STATE='curated_development_not_a_release'
EXPECTED_SOURCE=json.loads('{"catalogKey":"rackclick-qnap-01","definitions":[{"color":"#252729","dimensionsMm":{"depth":226.5,"height":165,"width":170},"groups":[{"count":2,"face":"rear","key":"rear-lan","name":"LAN","powerRole":"unspecified","prefix":"LAN ","type":"rj45"}],"identity":{"family":"TS-x64","manufacturer":"QNAP","model":"TS-464","sku":"TS-464-8G"},"key":"qnap-ts464-8g","kind":"desktop","passthrough":null,"provenance":{"assets":[],"kind":"manufacturer-specification","source":"https://www.qnap.com/en/product/ts-464/specs/hardware/TS-464-8G.pdf"},"rackUnits":0,"revision":"qnap-20261030-v1","slots":[]}],"formatVersion":1}')
EXPECTED_FACTS=json.loads('{"facts":{"depthMm":226.5,"dimensionsExcludeFootPad":true,"ethernetMbps":2500,"heightMm":165,"kind":"desktop","poe":false,"rearRj45":2,"totalHeightWithFeetMm":null,"widthMm":170},"formatVersion":1,"geometry":"Own interactive flat drawing; approximate colors; front closed cover and gold right stripe. No physical hardware revision asserted.","guide":{"documentDate":"06/02/2023","documentVersion":7,"pdfSha256":"5773a3346c41c689f814d599d521964633c3d40f8dc265f7f5e2279b10324523","url":"https://download.qnap.com/TechnicalDocument/Storage/SMB%20NAS/ts-x62%26x64/ts-x62%26x64-ug-en-us.pdf"},"hardwareRevision":null,"locators":{"dimensions":"Exact TS-464-8G hardware PDFpage2: H165xW170xD226.5mm, foot pads excluded. Generic up-to30mm note does not establish this model foot height.","front":"Guide PDFpages9-10 TS-462/TS-464 front with closed cover, status column at right; official family front photograph has gold right stripe.","ports":"Guide PDFpage13 TS-464 upper figure; PDFpage17 TS-x64 numbering LAN1upper and LAN2lower; two2.5GbE RJ45."},"model":"TS-464","mountScope":"Existing own shelf-5u main440x190x300mm represents nominal body dimensions only. Total installed height including feet is unknown. Check complete height, clearance, mechanical load and ventilation before physical installation; no certified fit is claimed. Historical shelf-2u60mm remains unchanged.","nonConnectableReferences":{"dcInput":1,"driveBays":4,"externalPowerAdapter":1,"fan":1,"hdmi":1,"pcieCover":1,"usbFront":1,"usbRear":3},"olderGuideDimensionsMm":{"depth":226,"height":168,"source":"Guide PDFpage7, TS-464 row; different from current exact-SKU nominal specification.","width":170},"pdfSha256":null,"photographScope":"Official TS-464 chassis-family photographs are private references only; installed8GB memory and optional cards cannot be established from photographs. No manufacturer photograph is redistributed in the application.","releaseDate":null,"retrieved":"2026-10-30","scope":"Exact TS-464-8G inventory identity, using manufacturer current nominal dimensions excluding foot pads. Only2rear Ethernet inventory connectors. No DC-to-AC-PDU link: external adapter needs a typed adapter contract. USB, HDMI, PCIe, optional NIC, M.2/SATA, disks, RAID, storage and telemetry are not modeled. Four bays do not assert installed drives.","sku":"TS-464-8G","specificationAccess":"Official web PDF reader; direct requests returned HTTP202 with empty body; no binary PDF hash claimed.","url":"https://www.qnap.com/en/product/ts-464/specs/hardware/TS-464-8G.pdf"}')
pretty=g.pretty
literal=g.literal

def sql_source(models,pins):
    lines=['-- Auto-generated by tools/build_hardware_catalog23.py; SQL001-022 are frozen.',
      '-- TS-464-8G nominal body dimensions exclude foot pads; complete installed height is unknown.',
      '-- Ethernet only: external DC adapter, USB, HDMI, PCIe and storage are out of scope.',
      '-- Existing sealing/publication triggers and runtime grants remain unchanged.']
    def insert(table,columns,values):lines.append('INSERT INTO '+table+' ('+columns+') VALUES ('+', '.join(map(literal,values))+');')
    for model,pin in zip(models,pins):
        pair=[model['key'],model['revision']];d=model['dimensionsMm']
        insert('hardware_definition','profile_key, revision, mount_kind, rack_units, width_mm, height_mm, depth_mm, color, definition_sha256, manufacturer, family, model, sku, provenance_kind, source_reference, sealed',pair+[model['kind'],model['rackUnits'],d['width'],d['height'],d['depth'],model['color'],pin['sha256']]+[model['identity'][key] for key in ('manufacturer','family','model','sku')]+[model['provenance']['kind'],model['provenance']['source'],False])
        for slot in model['slots']:
            sd=slot['dimensionsMm'];insert('hardware_mount_slot','profile_key, revision, slot_key, width_mm, height_mm, depth_mm',pair+[slot['key'],sd['width'],sd['height'],sd['depth']])
        for order,group in enumerate(model['groups']):
            insert('hardware_group_template','profile_key, revision, group_key, sort_order, type, port_count, face, name, prefix, power_role',pair+[group['key'],order,group['type'],group['count'],group['face'],group['name'],group['prefix'],group['powerRole']])
        lines.append('UPDATE hardware_definition SET sealed=true WHERE profile_key='+literal(pair[0])+' AND revision='+literal(pair[1])+';')
    return ('\n'.join(lines)+'\n').encode('utf-8')

def targets_source(inputs):
    return (g.targets_source(inputs).decode('ascii')
        .replace('build_hardware_catalog22.py','build_hardware_catalog23.py')
        .replace('DiskStation','Qnap').replace('diskstation_catalog','qnap_catalog')).encode('ascii')

def compile_catalog(root):
    raw={name:c.path(root,name).read_bytes() for name in (SOURCE,FACTS,LOCK,BASE)}
    source=c.load(raw[SOURCE]);facts=c.load(raw[FACTS]);lock=c.load(raw[LOCK])
    c.fields(lock,'formatVersion targetSchema sourceSha256 factsSha256 baseMigrationSha256 definitions state','qnap_lock_invalid')
    c.require(type(lock['formatVersion']) is int and lock['formatVersion']==1 and type(lock['targetSchema']) is int and lock['targetSchema']==23 and lock['state']==STATE,'qnap_target_unsupported')
    for name,field in ((SOURCE,'sourceSha256'),(FACTS,'factsSha256'),(BASE,'baseMigrationSha256')):c.require(c.sha(raw[name])==lock[field],'qnap_input_changed')
    # Reviewed scope is closed even when an input is repinned by a caller.
    c.require(c.canonical(source)==c.canonical(EXPECTED_SOURCE),'qnap_model_not_reviewed')
    c.require(c.canonical(facts)==c.canonical(EXPECTED_FACTS),'qnap_facts_mismatch')
    models=source['definitions'];pins=[dict(key=m['key'],revision=m['revision'],sha256=c.sha(c.canonical(m))) for m in models]
    c.require(lock['definitions']==pins,'qnap_definition_not_reviewed')
    server=c.server_source(source,commercial=True).decode('ascii').replace('tools/build_hardware_catalog.py;','tools/build_hardware_catalog23.py;').replace('internal static class CommercialHardwareProfiles','internal static class QnapHardwareProfiles')
    # Preserve the one-revision projection contract without changing the helper.
    views=[]
    for model in models:
        view=c.projection(dict(definitions=[model]));view['synthetic']=model['provenance']['kind']=='own-synthetic'
        row=view['profiles'][0]
        if not view['synthetic']:
            row.update(identity=model['identity'],source=model['provenance']['source'])
        for group,original in zip(row['groups'],model['groups']):group['powerRole']=original['powerRole']
        views.append(view)
    outputs={SERVER:server.encode('ascii'),FRONTEND:pretty(views[0]),SQL:sql_source(models,pins)}
    inputs={name:c.sha(value) for name,value in raw.items()}
    outputs[MANIFEST]=pretty(dict(formatVersion=1,targetSchema=23,catalogKey=source['catalogKey'],state=STATE,inputs=inputs,files={name:c.sha(value) for name,value in outputs.items()},definitions=pins))
    outputs[TARGETS]=targets_source({**inputs,**{name:c.sha(value) for name,value in outputs.items()}})
    return outputs

def run(root,write=False):
    outputs=compile_catalog(root);targets={name:c.path(root,name) for name in outputs}
    for target in targets.values():
        c.require(not target.exists() or target.is_file(),'qnap_output_invalid')
        c.require(all(not p.exists() or p.is_dir() for p in target.parents),'qnap_output_invalid')
    if write:
        staged={}
        try:
            for name,target in targets.items():
                target.parent.mkdir(parents=True,exist_ok=True);fd,temporary=tempfile.mkstemp(prefix='.catalog23-',dir=target.parent);staged[name]=temporary
                with os.fdopen(fd,'wb') as stream:stream.write(outputs[name]);stream.flush();os.fsync(stream.fileno())
            for name,target in targets.items():os.replace(staged[name],target)
        finally:
            for temporary in staged.values():
                if os.path.lexists(temporary):os.unlink(temporary)
    else:
        for name,target in targets.items():c.require(target.is_file() and target.read_bytes()==outputs[name],'qnap_catalog_stale')
    return dict(status='written' if write else 'verified',targetSchema=23,definitions=1,files={name:c.sha(value) for name,value in outputs.items()},databaseChanged=False)

def main():
    parser=argparse.ArgumentParser(description=__doc__);mode=parser.add_mutually_exclusive_group(required=True);mode.add_argument('--check',action='store_true');mode.add_argument('--write',action='store_true');args=parser.parse_args()
    try:print(json.dumps(run(ROOT,write=args.write)));return 0
    except (c.CatalogError,OSError) as error:print(json.dumps(dict(status='failed',code=str(error) if isinstance(error,c.CatalogError) else 'qnap_io_failed')));return 1
if __name__=='__main__':sys.exit(main())
